mapper.select:
SELECT d.id, d.name, d.parent_id, d.dep_no, d.director_id, e.name as director_name, d.status, d.gradeid, dg.name as grade_name, d.tenant_id, IFNULL(emp_stats.employee_count, 0) as employee_count, IFNULL(pos_stats.position_count, 0) as position_count FROM department d LEFT JOIN employee e ON d.director_id = e.id AND e.deleted = 0 LEFT JOIN department_grade dg ON d.gradeid = dg.id AND dg.deleted = 0 LEFT JOIN ( SELECT department_id, COUNT(*) as employee_count FROM employee WHERE deleted = 0 AND status IN (1, 2) GROUP BY department_id ) emp_stats ON d.id = emp_stats.department_id LEFT JOIN ( SELECT department_id, COUNT(*) as position_count FROM work_position WHERE deleted = 0 AND status = 1 GROUP BY department_id ) pos_stats ON d.id = pos_stats.department_id WHERE d.deleted = 0 AND d.tenant_id = #{tenantId}
AND d.parent_id = #{parentId}
AND d.parent_id = 0
AND d.status = 1
ORDER BY d.gradeid, d.created_at

SELECT d.*, pd.name as parent_name, dg.name as grade_name, e.name as director_name, IFNULL(emp_stats.employee_count, 0) as employee_count, IFNULL(pos_stats.position_count, 0) as position_count FROM department d LEFT JOIN department pd ON d.parent_id = pd.id AND pd.deleted = 0 LEFT JOIN department_grade dg ON d.gradeid = dg.id AND dg.deleted = 0 LEFT JOIN employee e ON d.director_id = e.id AND e.deleted = 0 LEFT JOIN ( SELECT department_id, COUNT(*) as employee_count FROM employee WHERE deleted = 0 AND status IN (1, 2) GROUP BY department_id ) emp_stats ON d.id = emp_stats.department_id LEFT JOIN ( SELECT department_id, COUNT(*) as position_count FROM work_position WHERE deleted = 0 AND status = 1 GROUP BY department_id ) pos_stats ON d.id = pos_stats.department_id WHERE d.deleted = 0 AND d.tenant_id = #{tenantId}
AND (d.name LIKE CONCAT('%', #{keyword}, '%') OR d.dep_no LIKE CONCAT('%', #{keyword}, '%'))
AND d.parent_id = #{parentId}
AND d.gradeid = #{gradeId}
AND d.status = #{status}
ORDER BY d.gradeid, d.created_at DESC

